window.aifExamData.domain1 = {"id":1,"title":"AIF-C01: Domain 1 Test Exam","subtitle":"Fundamentals of AI and ML","weight":"20%","questions":[{"q":"A retail company has five years of labeled customer records. Each record indicates whether the customer renewed a subscription. The company wants to predict renewal for new customers. Which ML approach is MOST appropriate?","opts":["Unsupervised clustering","Supervised regression","Supervised classification","Reinforcement learning"],"ans":[2],"why":"The data is labeled and the target is a discrete category, so supervised classification is appropriate.","explanation":{"correctAnswer":"C. Supervised classification","correctReason":"The data is labeled and the target is a discrete category, so supervised classification is appropriate. The key signal is **labeled examples + a categorical target**.","incorrectReasons":{"0":"Groups similar unlabeled examples but does not pursue goals or invoke tools. Here, the deciding detail is labeled examples + a categorical target, so this option describes a different need.","1":"Learns from labeled examples to predict a continuous numeric value. Here, the deciding detail is labeled examples + a categorical target, so this option describes a different need.","3":"Learns actions through rewards and penalties. Here, the deciding detail is labeled examples + a categorical target, so this option describes a different need."},"examClue":"**labeled examples + a categorical target**","examTip":"Signal: **labeled examples + a categorical target**. Decision rule: use supervised classification. Contrast: a continuous numeric target points to regression; unlabeled grouping points to clustering.","transferCheck":"","rememberThis":"","takeaway":{"signal":"**labeled examples + a categorical target**","think":"use supervised classification","contrast":"a continuous numeric target points to regression; unlabeled grouping points to clustering."}},"status":"kept mostly unchanged","task":"1.1","taskName":"Explain basic AI concepts and terminologies","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Supervised, Unsupervised, and Reinforcement Learning","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Supervised-Unsupervised-and-Reinforcement-Learning/page"}},{"q":"A predictive-maintenance team has labeled historical sensor data and wants to estimate the number of operating hours remaining before each machine is likely to fail. Which ML technique BEST fits the target?","opts":["Regression","Classification","Clustering","Reinforcement learning"],"ans":[0],"why":"The target is a continuous numeric value, so this is regression.","explanation":{"correctAnswer":"A. Regression","correctReason":"The target is a continuous numeric value, so this is regression. The key signal is the output is a **continuous numeric value**.","incorrectReasons":{"1":"Predicts a discrete category or class. Here, the deciding detail is the output is a continuous numeric value, so this option describes a different need.","2":"Groups similar unlabeled observations. Here, the deciding detail is the output is a continuous numeric value, so this option describes a different need.","3":"Learns actions through rewards and penalties. Here, the deciding detail is the output is a continuous numeric value, so this option describes a different need."},"examClue":"the output is a **continuous numeric value**","examTip":"Signal: the output is a **continuous numeric value**. Decision rule: choose regression. Contrast: if the output is a named category, classification is the closer fit.","transferCheck":"","rememberThis":"","takeaway":{"signal":"the output is a **continuous numeric value**","think":"choose regression","contrast":"if the output is a named category, classification is the closer fit."}},"status":"substantially revised","task":"1.2","taskName":"Identify practical use cases for AI","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Supervised, Unsupervised, and Reinforcement Learning","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Supervised-Unsupervised-and-Reinforcement-Learning/page"}},{"q":"A retailer has millions of purchase histories but no customer-segment labels. It wants the data to reveal groups of customers with similar buying behavior. Which approach should the retailer use?","opts":["Classification","Regression","Reinforcement learning","Clustering"],"ans":[3],"why":"Grouping similar unlabeled examples is clustering.","explanation":{"correctAnswer":"D. Clustering","correctReason":"Grouping similar unlabeled examples is clustering. The key signal is **unlabeled data + discover natural groups**.","incorrectReasons":{"0":"Predicts a discrete category or class. Here, the deciding detail is unlabeled data + discover natural groups, so this option describes a different need.","1":"Predicts a continuous numeric value. Here, the deciding detail is unlabeled data + discover natural groups, so this option describes a different need.","2":"Learns actions through rewards and penalties. Here, the deciding detail is unlabeled data + discover natural groups, so this option describes a different need."},"examClue":"**unlabeled data + discover natural groups**","examTip":"Signal: **unlabeled data + discover natural groups**. Decision rule: choose clustering. Contrast: if known labels exist and you predict one of them, that is supervised classification.","transferCheck":"","rememberThis":"","takeaway":{"signal":"**unlabeled data + discover natural groups**","think":"choose clustering","contrast":"if known labels exist and you predict one of them, that is supervised classification."}},"status":"substantially revised","task":"1.2","taskName":"Identify practical use cases for AI","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Supervised, Unsupervised, and Reinforcement Learning","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Supervised-Unsupervised-and-Reinforcement-Learning/page"}},{"q":"A warehouse robot repeatedly chooses routes. It receives positive feedback for fast, safe deliveries and penalties for collisions or delays. Which learning method is being used?","opts":["Supervised learning","Reinforcement learning","Unsupervised learning","Transfer learning"],"ans":[1],"why":"Learning through actions, rewards, and penalties is reinforcement learning.","explanation":{"correctAnswer":"B. Reinforcement learning","correctReason":"Learning through actions, rewards, and penalties is reinforcement learning. The key signal is the system learns from **actions, rewards, and penalties**.","incorrectReasons":{"0":"Learns from labeled examples to predict known targets. Here, the deciding detail is the system learns from actions, rewards, and penalties, so this option describes a different need.","2":"Works with unlabeled data to discover structure such as groups or patterns. Here, the deciding detail is the system learns from actions, rewards, and penalties, so this option describes a different need.","3":"Reuses learned representations from an existing model for a related task. Here, the deciding detail is the system learns from actions, rewards, and penalties, so this option describes a different need."},"examClue":"the system learns from **actions, rewards, and penalties**","examTip":"Signal: the system learns from **actions, rewards, and penalties**. Decision rule: think reinforcement learning. Contrast: labeled input-output examples point to supervised learning.","transferCheck":"","rememberThis":"","takeaway":{"signal":"the system learns from **actions, rewards, and penalties**","think":"think reinforcement learning","contrast":"labeled input-output examples point to supervised learning."}},"status":"substantially revised","task":"1.1","taskName":"Explain basic AI concepts and terminologies","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Supervised, Unsupervised, and Reinforcement Learning","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Supervised-Unsupervised-and-Reinforcement-Learning/page"}},{"q":"After training, a classifier achieves 99% accuracy on its training data but only 74% on unseen validation data. Which condition BEST explains the gap?","opts":["Overfitting","Underfitting","Data normalization","Class balancing"],"ans":[0],"why":"Strong training performance with significantly weaker validation performance indicates overfitting.","explanation":{"correctAnswer":"A. Overfitting","correctReason":"Strong training performance with significantly weaker validation performance indicates overfitting. The key signal is **training performance is much better than validation performance**.","incorrectReasons":{"1":"Occurs when a model is too simple or insufficiently trained to capture important patterns. Here, the deciding detail is training performance is much better than validation performance, so this option describes a different need.","2":"Rescales or transforms data; it does not by itself fix generalization gaps. Here, the deciding detail is training performance is much better than validation performance, so this option describes a different need.","3":"Addresses class imbalance through weighting or sampling. Here, the deciding detail is training performance is much better than validation performance, so this option describes a different need."},"examClue":"**training performance is much better than validation performance**","examTip":"Signal: **training performance is much better than validation performance**. Decision rule: suspect overfitting. Contrast: poor performance on both training and validation data is more consistent with underfitting.","transferCheck":"What result pattern would make **underfitting** the better diagnosis instead?","rememberThis":"","takeaway":{"signal":"**training performance is much better than validation performance**","think":"suspect overfitting","contrast":"poor performance on both training and validation data is more consistent with underfitting."}},"status":"substantially revised","task":"1.3","taskName":"Describe the AI/ML development lifecycle","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: ML Development Lifecycle and the ML Pipeline","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/ML-Development-Lifecycle-and-the-ML-Pipeline/page"}},{"q":"A simple model performs poorly on both the training set and the validation set, and additional training does not materially improve either result. Which issue is MOST likely?","opts":["High variance","Overfitting","Underfitting","Data leakage"],"ans":[2],"why":"Poor performance on both training and validation data typically indicates underfitting.","explanation":{"correctAnswer":"C. Underfitting","correctReason":"Poor performance on both training and validation data typically indicates underfitting. The key signal is **poor performance even on training data**.","incorrectReasons":{"0":"Is associated with sensitivity to training data and often with overfitting. Here, the deciding detail is poor performance even on training data, so this option describes a different need.","1":"Occurs when a model learns training data too closely and generalizes poorly. Here, the deciding detail is poor performance even on training data, so this option describes a different need.","3":"Is unauthorized or unintended disclosure of sensitive information. Here, the deciding detail is poor performance even on training data, so this option describes a different need."},"examClue":"**poor performance even on training data**","examTip":"Signal: **poor performance even on training data**. Decision rule: suspect underfitting. Contrast: strong training but weak validation performance indicates overfitting.","transferCheck":"","rememberThis":"","takeaway":{"signal":"**poor performance even on training data**","think":"suspect underfitting","contrast":"strong training but weak validation performance indicates overfitting."}},"status":"substantially revised","task":"1.3","taskName":"Describe the AI/ML development lifecycle","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: ML Development Lifecycle and the ML Pipeline","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/ML-Development-Lifecycle-and-the-ML-Pipeline/page"}},{"q":"A fraud dataset contains 99.5% legitimate transactions and 0.5% fraud. A model predicts almost everything as legitimate and still reports very high overall performance. Which metric is MOST likely to be misleading if used by itself?","opts":["Recall","Precision","F1 score","Accuracy"],"ans":[3],"why":"Accuracy can be misleading on highly imbalanced datasets.","explanation":{"correctAnswer":"D. Accuracy","correctReason":"Accuracy can be misleading on highly imbalanced datasets. The key signal is a **severely imbalanced dataset** with a majority class.","incorrectReasons":{"0":"Measures how many actual positives are found and is sensitive to false negatives. Here, the deciding detail is a severely imbalanced dataset with a majority class, so this option describes a different need.","1":"Measures how many predicted positives are truly positive and is sensitive to false positives. Here, the deciding detail is a severely imbalanced dataset with a majority class, so this option describes a different need.","2":"Balances precision and recall using a harmonic mean. Here, the deciding detail is a severely imbalanced dataset with a majority class, so this option describes a different need."},"examClue":"a **severely imbalanced dataset** with a majority class","examTip":"Signal: a **severely imbalanced dataset** with a majority class. Decision rule: do not trust accuracy alone. Contrast: precision, recall, or F1 can reveal minority-class performance that overall accuracy hides.","transferCheck":"","rememberThis":"","takeaway":{"signal":"a **severely imbalanced dataset** with a majority class","think":"do not trust accuracy alone","contrast":"precision, recall, or F1 can reveal minority-class performance that overall accuracy hides."}},"status":"substantially revised","task":"1.3","taskName":"Describe the AI/ML development lifecycle","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Basic AI Concepts and Terminologies","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Basic-AI-Concepts-and-Terminologies/page"}},{"q":"A screening system is used to identify patients who may have a serious disease. Missing a patient who actually has the disease is much more costly than sending a healthy patient for follow-up. Which metric should the team prioritize?","opts":["Recall","Precision","Mean squared error","R-squared"],"ans":[0],"why":"Missing an actual positive is a false negative; recall is the key metric.","explanation":{"correctAnswer":"A. Recall","correctReason":"Missing an actual positive is a false negative; recall is the key metric. The key signal is **false negatives are especially costly**.","incorrectReasons":{"1":"Measures how many predicted positives are truly positive and is sensitive to false positives. Here, the deciding detail is false negatives are especially costly, so this option describes a different need.","2":"Is a regression error metric based on squared numeric errors. Here, the deciding detail is false negatives are especially costly, so this option describes a different need.","3":"Is a regression metric for explained variance. Here, the deciding detail is false negatives are especially costly, so this option describes a different need."},"examClue":"**false negatives are especially costly**","examTip":"Signal: **false negatives are especially costly**. Decision rule: prioritize recall. Contrast: when false positives are the main cost, precision becomes more important.","transferCheck":"If the scenario changed so that false positives were more costly than false negatives, which metric would become more important?","rememberThis":"","takeaway":{"signal":"**false negatives are especially costly**","think":"prioritize recall","contrast":"when false positives are the main cost, precision becomes more important."}},"status":"substantially revised","task":"1.3","taskName":"Describe the AI/ML development lifecycle","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Basic AI Concepts and Terminologies","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Basic-AI-Concepts-and-Terminologies/page"}},{"q":"An email filter is causing too many legitimate messages to be placed in the spam folder. The team specifically wants to reduce these false alarms among messages predicted as spam. Which metric should it prioritize?","opts":["Recall","MAE","Precision","RMSE"],"ans":[2],"why":"Reducing false positives among predicted positives means prioritizing precision.","explanation":{"correctAnswer":"C. Precision","correctReason":"Reducing false positives among predicted positives means prioritizing precision. The key signal is **false positives are especially costly**.","incorrectReasons":{"0":"Measures how many actual positives are found and is sensitive to false negatives. Here, the deciding detail is false positives are especially costly, so this option describes a different need.","1":"Is a regression error metric based on absolute numeric errors. Here, the deciding detail is false positives are especially costly, so this option describes a different need.","3":"Is a regression error metric that penalizes larger errors more strongly. Here, the deciding detail is false positives are especially costly, so this option describes a different need."},"examClue":"**false positives are especially costly**","examTip":"Signal: **false positives are especially costly**. Decision rule: prioritize precision. Contrast: when missing true positives is the bigger risk, prioritize recall.","transferCheck":"If the scenario changed so that missing true positives were the main risk, which metric would become more important?","rememberThis":"","takeaway":{"signal":"**false positives are especially costly**","think":"prioritize precision","contrast":"when missing true positives is the bigger risk, prioritize recall."}},"status":"substantially revised","task":"1.3","taskName":"Describe the AI/ML development lifecycle","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Basic AI Concepts and Terminologies","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Basic-AI-Concepts-and-Terminologies/page"}},{"q":"A team has separate training, validation, and test datasets. It is comparing several model configurations before selecting the final candidate. Which dataset should be used for this model-selection step?","opts":["Training set","Validation set","Test set","Production set"],"ans":[1],"why":"The validation set is used for tuning and model selection.","explanation":{"correctAnswer":"B. Validation set","correctReason":"The validation set is used for tuning and model selection. The key signal is the team is **choosing among model configurations before final evaluation**.","incorrectReasons":{"0":"Is used to fit model parameters. Here, the deciding detail is the team is choosing among model configurations before final evaluation, so this option describes a different need.","2":"Is reserved for final, unbiased evaluation of the selected model. Here, the deciding detail is the team is choosing among model configurations before final evaluation, so this option describes a different need.","3":"Is not a standard substitute for a validation set during model development. Here, the deciding detail is the team is choosing among model configurations before final evaluation, so this option describes a different need."},"examClue":"the team is **choosing among model configurations before final evaluation**","examTip":"Signal: the team is **choosing among model configurations before final evaluation**. Decision rule: use validation data. Contrast: preserve the test set for the final unbiased check.","transferCheck":"","rememberThis":"","takeaway":{"signal":"the team is **choosing among model configurations before final evaluation**","think":"use validation data","contrast":"preserve the test set for the final unbiased check."}},"status":"substantially revised","task":"1.3","taskName":"Describe the AI/ML development lifecycle","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: ML Development Lifecycle and the ML Pipeline","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/ML-Development-Lifecycle-and-the-ML-Pipeline/page"}},{"q":"A team evaluates a new model and discovers that examples from the final holdout dataset were accidentally used while fitting the model. What problem does this create?","opts":["Feature scaling","Underfitting","Batch inference","Data leakage"],"ans":[3],"why":"Using test data during training causes data leakage and invalidates evaluation.","explanation":{"correctAnswer":"D. Data leakage","correctReason":"Using test data during training causes data leakage and invalidates evaluation. The key signal is information from the **holdout/test set enters training**.","incorrectReasons":{"0":"Standardizes or normalizes numeric feature ranges; it does not fix leakage from the holdout set. Here, the deciding detail is information from the holdout/test set enters training, so this option describes a different need.","1":"Occurs when a model is too simple or insufficiently trained to capture important patterns. Here, the deciding detail is information from the holdout/test set enters training, so this option describes a different need.","2":"Scores many inputs asynchronously when immediate per-request responses are unnecessary. Here, the deciding detail is information from the holdout/test set enters training, so this option describes a different need."},"examClue":"information from the **holdout/test set enters training**","examTip":"Signal: information from the **holdout/test set enters training**. Decision rule: identify data leakage. Contrast: normal preprocessing learned only from training data is not leakage.","transferCheck":"","rememberThis":"","takeaway":{"signal":"information from the **holdout/test set enters training**","think":"identify data leakage","contrast":"normal preprocessing learned only from training data is not leakage."}},"status":"substantially revised","task":"1.3","taskName":"Describe the AI/ML development lifecycle","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: ML Development Lifecycle and the ML Pipeline","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/ML-Development-Lifecycle-and-the-ML-Pipeline/page"}},{"q":"A classification model has already been trained and deployed. It now receives a newly submitted support ticket and returns a category. Which lifecycle activity is occurring?","opts":["Training","Labeling","Inferencing","Feature engineering"],"ans":[2],"why":"Using a trained model on new data is inference.","explanation":{"correctAnswer":"C. Inferencing","correctReason":"Using a trained model on new data is inference. The key signal is the model is **already trained and is predicting on new input**.","incorrectReasons":{"0":"Fits model parameters from data. Here, the deciding detail is the model is already trained and is predicting on new input, so this option describes a different need.","1":"Creates target labels or annotations for training data. Here, the deciding detail is the model is already trained and is predicting on new input, so this option describes a different need.","3":"Creates or transforms input features; it is not the act of using a trained model. Here, the deciding detail is the model is already trained and is predicting on new input, so this option describes a different need."},"examClue":"the model is **already trained and is predicting on new input**","examTip":"Signal: the model is **already trained and is predicting on new input**. Decision rule: this is inference. Contrast: training changes model parameters.","transferCheck":"","rememberThis":"","takeaway":{"signal":"the model is **already trained and is predicting on new input**","think":"this is inference","contrast":"training changes model parameters."}},"status":"substantially revised","task":"1.1","taskName":"Explain basic AI concepts and terminologies","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Supervised, Unsupervised, and Reinforcement Learning","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Supervised-Unsupervised-and-Reinforcement-Learning/page"}},{"q":"A retailer needs predictions for 20 million archived records by the next morning. Individual predictions do not need to be returned interactively. Which inference pattern is MOST appropriate?","opts":["Batch inference","Real-time inference","Streaming training","Reinforcement learning"],"ans":[0],"why":"Batch inference suits high-volume workloads without immediate-response requirements.","explanation":{"correctAnswer":"A. Batch inference","correctReason":"Batch inference suits high-volume workloads without immediate-response requirements. The key signal is **large volume + no immediate per-request response**.","incorrectReasons":{"1":"Returns low-latency predictions synchronously for interactive requests. Here, the deciding detail is large volume + no immediate per-request response, so this option describes a different need.","2":"Is the broad field of creating systems that perform tasks associated with human intelligence. Here, the deciding detail is large volume + no immediate per-request response, so this option describes a different need.","3":"Learns actions through rewards and penalties. Here, the deciding detail is large volume + no immediate per-request response, so this option describes a different need."},"examClue":"**large volume + no immediate per-request response**","examTip":"Signal: **large volume + no immediate per-request response**. Decision rule: batch inference fits. Contrast: interactive millisecond predictions call for real-time inference.","transferCheck":"","rememberThis":"","takeaway":{"signal":"**large volume + no immediate per-request response**","think":"batch inference fits","contrast":"interactive millisecond predictions call for real-time inference."}},"status":"substantially revised","task":"1.1","taskName":"Explain basic AI concepts and terminologies","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Supervised, Unsupervised, and Reinforcement Learning","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Supervised-Unsupervised-and-Reinforcement-Learning/page"}},{"q":"A payment service must score each transaction for fraud while the transaction is being authorized. The response must return in milliseconds. Which inference pattern BEST meets the requirement?","opts":["Batch inference","Offline training","Manual labeling","Real-time inference"],"ans":[3],"why":"Low-latency per-request prediction requires real-time inference.","explanation":{"correctAnswer":"D. Real-time inference","correctReason":"Low-latency per-request prediction requires real-time inference. The key signal is **interactive, synchronous, low-latency predictions**.","incorrectReasons":{"0":"Scores many inputs asynchronously when immediate per-request responses are unnecessary. Here, the deciding detail is interactive, synchronous, low-latency predictions, so this option describes a different need.","1":"Is the broad field of creating systems that perform tasks associated with human intelligence. Here, the deciding detail is interactive, synchronous, low-latency predictions, so this option describes a different need.","2":"Creates target labels or annotations for training data. Here, the deciding detail is interactive, synchronous, low-latency predictions, so this option describes a different need."},"examClue":"**interactive, synchronous, low-latency predictions**","examTip":"Signal: **interactive, synchronous, low-latency predictions**. Decision rule: real-time inference. Contrast: large offline workloads with no urgency fit batch inference.","transferCheck":"","rememberThis":"","takeaway":{"signal":"**interactive, synchronous, low-latency predictions**","think":"real-time inference","contrast":"large offline workloads with no urgency fit batch inference."}},"status":"substantially revised","task":"1.1","taskName":"Explain basic AI concepts and terminologies","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Basic AI Concepts and Terminologies","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Basic-AI-Concepts-and-Terminologies/page"}},{"q":"A customer-experience team wants a managed AWS service to identify sentiment and named entities in incoming email without building its own NLP model. Which service is MOST appropriate?","opts":["Amazon Translate","Amazon Comprehend","Amazon Transcribe","Amazon Lex"],"ans":[1],"why":"Amazon Comprehend provides NLP capabilities such as sentiment and entity detection.","explanation":{"correctAnswer":"B. Amazon Comprehend","correctReason":"Amazon Comprehend provides NLP capabilities such as sentiment and entity detection. The key signal is **sentiment, entities, or language understanding**.","incorrectReasons":{"0":"Translates text between languages. Here, the deciding detail is sentiment, entities, or language understanding, so this option describes a different need.","2":"Converts speech or audio into text. Here, the deciding detail is sentiment, entities, or language understanding, so this option describes a different need.","3":"Builds conversational interfaces using text and speech. Here, the deciding detail is sentiment, entities, or language understanding, so this option describes a different need."},"examClue":"**sentiment, entities, or language understanding**","examTip":"Signal: **sentiment, entities, or language understanding**. Decision rule: consider Amazon Comprehend. Contrast: Translate changes languages; Transcribe converts speech to text; Lex builds conversational interfaces.","transferCheck":"If the input were recorded speech that needed text rather than written text needing sentiment analysis, which service would become the better fit?","rememberThis":"","takeaway":{"signal":"**sentiment, entities, or language understanding**","think":"consider Amazon Comprehend","contrast":"Translate changes languages; Transcribe converts speech to text; Lex builds conversational interfaces."}},"status":"substantially revised","task":"1.2","taskName":"Identify practical use cases for AI","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Overview of AI and ML Services on AWS","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Overview-of-AI-and-ML-Services-on-AWS/page"}},{"q":"A contact center stores recorded calls in Amazon S3 and wants searchable text transcripts for downstream analysis. Which managed AWS AI service BEST meets the requirement?","opts":["Amazon Polly","Amazon Translate","Amazon Transcribe","Amazon Comprehend"],"ans":[2],"why":"Amazon Transcribe converts speech to text.","explanation":{"correctAnswer":"C. Amazon Transcribe","correctReason":"Amazon Transcribe converts speech to text. The key signal is **audio or speech must become text**.","incorrectReasons":{"0":"Converts text into natural-sounding speech. Here, the deciding detail is audio or speech must become text, so this option describes a different need.","1":"Translates text between languages. Here, the deciding detail is audio or speech must become text, so this option describes a different need.","3":"Is a managed NLP service for sentiment, entities, key phrases, and other language-understanding tasks. Here, the deciding detail is audio or speech must become text, so this option describes a different need."},"examClue":"**audio or speech must become text**","examTip":"Signal: **audio or speech must become text**. Decision rule: Transcribe. Contrast: Polly goes the opposite direction, text to speech.","transferCheck":"If the requirement changed from speech-to-text to text-to-speech, which service would replace Transcribe?","rememberThis":"","takeaway":{"signal":"**audio or speech must become text**","think":"Transcribe","contrast":"Polly goes the opposite direction, text to speech."}},"status":"substantially revised","task":"1.2","taskName":"Identify practical use cases for AI","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Overview of AI and ML Services on AWS","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Overview-of-AI-and-ML-Services-on-AWS/page"}},{"q":"A reading application receives text and must speak it aloud using natural-sounding voices. Which managed AWS AI service should the team use?","opts":["Amazon Polly","Amazon Transcribe","Amazon Lex","Amazon Translate"],"ans":[0],"why":"Amazon Polly converts text to speech.","explanation":{"correctAnswer":"A. Amazon Polly","correctReason":"Amazon Polly converts text to speech. The key signal is **written text must be spoken aloud**.","incorrectReasons":{"1":"Converts speech or audio into text. Here, the deciding detail is written text must be spoken aloud, so this option describes a different need.","2":"Builds conversational interfaces using text and speech. Here, the deciding detail is written text must be spoken aloud, so this option describes a different need.","3":"Translates text between languages. Here, the deciding detail is written text must be spoken aloud, so this option describes a different need."},"examClue":"**written text must be spoken aloud**","examTip":"Signal: **written text must be spoken aloud**. Decision rule: Polly. Contrast: Transcribe converts speech to text.","transferCheck":"If the requirement changed from text-to-speech to speech-to-text, which service would replace Polly?","rememberThis":"","takeaway":{"signal":"**written text must be spoken aloud**","think":"Polly","contrast":"Transcribe converts speech to text."}},"status":"substantially revised","task":"1.2","taskName":"Identify practical use cases for AI","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Overview of AI and ML Services on AWS","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Overview-of-AI-and-ML-Services-on-AWS/page"}},{"q":"An insurer receives scanned claim forms and needs to extract printed text, tables, and key-value fields for downstream processing. Which AWS service BEST fits this requirement?","opts":["Amazon Rekognition","Amazon Textract","Amazon Comprehend","Amazon Transcribe"],"ans":[1],"why":"Amazon Textract extracts text and structured information from documents.","explanation":{"correctAnswer":"B. Amazon Textract","correctReason":"Amazon Textract extracts text and structured information from documents. The key signal is **scanned documents + forms/tables/key-value fields**.","incorrectReasons":{"0":"Analyzes images and video for labels, objects, faces, moderation, and other vision use cases. Here, the deciding detail is scanned documents + forms/tables/key-value fields, so this option describes a different need.","2":"Is a managed NLP service for sentiment, entities, key phrases, and other language-understanding tasks. Here, the deciding detail is scanned documents + forms/tables/key-value fields, so this option describes a different need.","3":"Converts speech or audio into text. Here, the deciding detail is scanned documents + forms/tables/key-value fields, so this option describes a different need."},"examClue":"**scanned documents + forms/tables/key-value fields**","examTip":"Signal: **scanned documents + forms/tables/key-value fields**. Decision rule: Textract. Contrast: Rekognition analyzes general image/video content, not structured document extraction.","transferCheck":"If the input were ordinary photographs and the goal were object/face analysis instead of document fields, which AWS service would become the stronger fit?","rememberThis":"","takeaway":{"signal":"**scanned documents + forms/tables/key-value fields**","think":"Textract","contrast":"Rekognition analyzes general image/video content, not structured document extraction."}},"status":"substantially revised","task":"1.2","taskName":"Identify practical use cases for AI","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Overview of AI and ML Services on AWS","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Overview-of-AI-and-ML-Services-on-AWS/page"}},{"q":"An ecommerce site wants to rank products differently for each shopper based on that shopper's interactions and preferences. Which managed AWS AI service is MOST appropriate?","opts":["Amazon Comprehend","Amazon Lex","Amazon Quick","Amazon Personalize"],"ans":[3],"why":"Amazon Personalize is designed for personalized recommendations.","explanation":{"correctAnswer":"D. Amazon Personalize","correctReason":"Amazon Personalize is designed for personalized recommendations. The key signal is **personalized ranking or recommendations from user interactions**.","incorrectReasons":{"0":"Is a managed NLP service for sentiment, entities, key phrases, and other language-understanding tasks. Here, the deciding detail is personalized ranking or recommendations from user interactions, so this option describes a different need.","1":"Builds conversational interfaces using text and speech. Here, the deciding detail is personalized ranking or recommendations from user interactions, so this option describes a different need.","2":"Is an AI-powered business workspace combining natural-language interaction, data, analytics, research, and automation. Here, the deciding detail is personalized ranking or recommendations from user interactions, so this option describes a different need."},"examClue":"**personalized ranking or recommendations from user interactions**","examTip":"Signal: **personalized ranking or recommendations from user interactions**. Decision rule: Personalize. Contrast: Comprehend understands language; Quick is a business AI workspace.","transferCheck":"","rememberThis":"","takeaway":{"signal":"**personalized ranking or recommendations from user interactions**","think":"Personalize","contrast":"Comprehend understands language; Quick is a business AI workspace."}},"status":"substantially revised","task":"1.2","taskName":"Identify practical use cases for AI","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Overview of AI and ML Services on AWS","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Overview-of-AI-and-ML-Services-on-AWS/page"}},{"q":"A compliance team needs a model for a tabular risk-scoring problem. The decision must be easy to explain to auditors, and a traditional ML model meets the required accuracy. Which approach is MOST appropriate?","opts":["Use a traditional interpretable ML model","Use the largest available foundation model","Use an image-generation diffusion model","Use a multi-agent system"],"ans":[0],"why":"A traditional ML model is the better fit when structured prediction and explainability satisfy the business requirement without the complexity of a foundation model.","task":"1.2","difficulty":"moderate","status":"replaced","taskName":"Identify practical use cases for AI","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","explanation":{"correctAnswer":"A. Use a traditional interpretable ML model","correctReason":"A traditional ML model is the better fit when structured prediction and explainability satisfy the business requirement without the complexity of a foundation model. The key signal is a **structured prediction task with strong explainability needs** where traditional ML meets quality.","incorrectReasons":{"1":"Is the broad field of creating systems that perform tasks associated with human intelligence. Here, the deciding detail is a structured prediction task with strong explainability needs where traditional ML meets quality, so this option describes a different need.","2":"Generates content through iterative denoising from an initially noisy representation. Here, the deciding detail is a structured prediction task with strong explainability needs where traditional ML meets quality, so this option describes a different need.","3":"Coordinates multiple specialized agents that communicate or divide work. Here, the deciding detail is a structured prediction task with strong explainability needs where traditional ML meets quality, so this option describes a different need."},"examClue":"a **structured prediction task with strong explainability needs** where traditional ML meets quality","examTip":"Signal: a **structured prediction task with strong explainability needs** where traditional ML meets quality. Decision rule: prefer the simpler interpretable approach. Contrast: foundation models are more useful when broad generative or language capabilities are required.","transferCheck":"","rememberThis":"","takeaway":{"signal":"a **structured prediction task with strong explainability needs** where traditional ML meets quality","think":"prefer the simpler interpretable approach","contrast":"foundation models are more useful when broad generative or language capabilities are required."}},"kodekloud":{"title":"KodeKloud: Basic AI Concepts and Terminologies","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Basic-AI-Concepts-and-Terminologies/page"}},{"q":"A retailer has a fixed business policy: every order over $200 receives free shipping. The policy is explicit, stable, and requires the exact same outcome every time. Which approach is MOST appropriate?","opts":["Deep learning model","Supervised classifier","Deterministic rule-based logic","Reinforcement learning agent"],"ans":[2],"why":"The logic is known and deterministic, so ML is unnecessary.","explanation":{"correctAnswer":"C. Deterministic rule-based logic","correctReason":"The logic is known and deterministic, so ML is unnecessary. The key signal is the business outcome is **explicit, exact, and rule-driven**.","incorrectReasons":{"0":"Uses multilayer neural networks and can learn complex patterns, but it is unnecessary when the business outcome is already fully specified by a simple rule. Here, the deciding detail is the business outcome is explicit, exact, and rule-driven, so this option describes a different need.","1":"Learns a category from labeled examples, but no learning is needed when the decision rule is already explicit. Here, the deciding detail is the business outcome is explicit, exact, and rule-driven, so this option describes a different need.","3":"Learns actions through rewards and penalties. Here, the deciding detail is the business outcome is explicit, exact, and rule-driven, so this option describes a different need."},"examClue":"the business outcome is **explicit, exact, and rule-driven**","examTip":"Signal: the business outcome is **explicit, exact, and rule-driven**. Decision rule: use deterministic logic rather than ML. Contrast: ML is useful when the system must infer a pattern or prediction from data.","transferCheck":"","rememberThis":"","takeaway":{"signal":"the business outcome is **explicit, exact, and rule-driven**","think":"use deterministic logic rather than ML","contrast":"ML is useful when the system must infer a pattern or prediction from data."}},"status":"substantially revised","task":"1.2","taskName":"Identify practical use cases for AI","difficulty":"moderate","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: Supervised, Unsupervised, and Reinforcement Learning","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Supervised-Unsupervised-and-Reinforcement-Learning/page"}},{"q":"A model performs very well on its training data but poorly on new validation examples. Which TWO actions are reasonable ways to improve generalization? (Select TWO.)","opts":["Apply regularization","Use more representative training data","Train on the test set","Increase complexity without validation","Remove the validation set"],"ans":[0,1],"why":"Regularization and more representative data can improve generalization.","explanation":{"correctAnswer":"A. Apply regularization / B. Use more representative training data","correctReason":"Regularization and more representative data can improve generalization. The key signal is **training performance is strong but validation performance is weak**, so the problem is generalization.","incorrectReasons":{"2":"Contaminates the final holdout and creates data leakage. Here, the deciding detail is training performance is strong but validation performance is weak, so the problem is generalization, so this option describes a different need.","3":"Can make overfitting worse and does not provide evidence that generalization improved. Here, the deciding detail is training performance is strong but validation performance is weak, so the problem is generalization, so this option describes a different need.","4":"Eliminates a key dataset used for model selection and makes it harder to detect generalization problems. Here, the deciding detail is training performance is strong but validation performance is weak, so the problem is generalization, so this option describes a different need."},"examClue":"**training performance is strong but validation performance is weak**, so the problem is generalization","examTip":"Signal: **training performance is strong but validation performance is weak**, so the problem is generalization. Decision rule: favor techniques that reduce overfitting, such as regularization or more representative data. Contrast: training on the test set or removing validation data destroys evaluation quality rather than improving generalization.","transferCheck":"","rememberThis":"","takeaway":{"signal":"**training performance is strong but validation performance is weak**, so the problem is generalization","think":"favor techniques that reduce overfitting, such as regularization or more representative data","contrast":"training on the test set or removing validation data destroys evaluation quality rather than improving generalization."}},"status":"substantially revised","task":"1.3","taskName":"Describe the AI/ML development lifecycle","difficulty":"challenging","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","kodekloud":{"title":"KodeKloud: ML Development Lifecycle and the ML Pipeline","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/ML-Development-Lifecycle-and-the-ML-Pipeline/page"}},{"q":"A travel application must interpret a user's goal, plan several steps, call external booking and mapping tools, and adjust its next action based on intermediate results. Which AI approach BEST fits this workload?","opts":["A single traditional regression model","Agentic AI","Unsupervised clustering","A deterministic one-step lookup"],"ans":[1],"why":"Agentic AI is appropriate when a system must pursue a goal across multiple steps, use tools, and adapt actions based on intermediate results.","task":"1.1","difficulty":"moderate","status":"replaced","taskName":"Explain basic AI concepts and terminologies","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","explanation":{"correctAnswer":"B. Agentic AI","correctReason":"Agentic AI is appropriate when a system must pursue a goal across multiple steps, use tools, and adapt actions based on intermediate results. The key signal is **multi-step goal + tool use + adaptation from intermediate results**.","incorrectReasons":{"0":"Predicts a numeric target from inputs; it does not orchestrate tools or multi-step actions. Here, the deciding detail is multi-step goal + tool use + adaptation from intermediate results, so this option describes a different need.","2":"Groups similar unlabeled examples but does not pursue goals or invoke tools. Here, the deciding detail is multi-step goal + tool use + adaptation from intermediate results, so this option describes a different need.","3":"Returns a fixed result from a direct lookup and does not plan or adapt across steps. Here, the deciding detail is multi-step goal + tool use + adaptation from intermediate results, so this option describes a different need."},"examClue":"**multi-step goal + tool use + adaptation from intermediate results**","examTip":"Signal: **multi-step goal + tool use + adaptation from intermediate results**. Decision rule: agentic AI is a strong fit. Contrast: a single prediction or generation call usually does not require an agent.","transferCheck":"","rememberThis":"","takeaway":{"signal":"**multi-step goal + tool use + adaptation from intermediate results**","think":"agentic AI is a strong fit","contrast":"a single prediction or generation call usually does not require an agent."}},"kodekloud":{"title":"KodeKloud: Supervised, Unsupervised, and Reinforcement Learning","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Supervised-Unsupervised-and-Reinforcement-Learning/page"}},{"q":"A document-processing workflow submits jobs that can take several minutes. The client should not keep a connection open while waiting and can retrieve results later. Which inference pattern BEST fits this requirement?","opts":["Real-time inference","Batch inference for a scheduled full dataset","Asynchronous inference","Model training"],"ans":[2],"why":"Asynchronous inference fits individual requests that take longer to process and do not require the client to wait synchronously.","task":"1.1","difficulty":"moderate","status":"replaced","taskName":"Explain basic AI concepts and terminologies","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","explanation":{"correctAnswer":"C. Asynchronous inference","correctReason":"Asynchronous inference fits individual requests that take longer to process and do not require the client to wait synchronously. The key signal is an **individual request may run for a while and the client should not wait synchronously**.","incorrectReasons":{"0":"Returns low-latency predictions synchronously for interactive requests. Here, the deciding detail is an individual request may run for a while and the client should not wait synchronously, so this option describes a different need.","1":"Scores many inputs asynchronously when immediate per-request responses are unnecessary. Here, the deciding detail is an individual request may run for a while and the client should not wait synchronously, so this option describes a different need.","3":"Changes model parameters; it is different from serving predictions. Here, the deciding detail is an individual request may run for a while and the client should not wait synchronously, so this option describes a different need."},"examClue":"an **individual request may run for a while and the client should not wait synchronously**","examTip":"Signal: an **individual request may run for a while and the client should not wait synchronously**. Decision rule: asynchronous inference. Contrast: batch inference is oriented to bulk datasets; real-time serves fast synchronous calls.","transferCheck":"","rememberThis":"","takeaway":{"signal":"an **individual request may run for a while and the client should not wait synchronously**","think":"asynchronous inference","contrast":"batch inference is oriented to bulk datasets; real-time serves fast synchronous calls."}},"kodekloud":{"title":"KodeKloud: Basic AI Concepts and Terminologies","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/Basic-AI-Concepts-and-Terminologies/page"}},{"q":"A deployed forecasting model initially performs well, but accuracy declines as customer behavior changes over several months. Which MLOps activity should the team prioritize?","opts":["Reuse the original test results indefinitely","Monitor production performance and retrain when needed","Increase the number of labels in the output","Replace inference with data labeling"],"ans":[1],"why":"MLOps includes monitoring production performance and retraining when data or model behavior changes.","task":"1.3","difficulty":"moderate","status":"replaced","taskName":"Describe the AI/ML development lifecycle","reference":"https://docs.aws.amazon.com/aws-certification/latest/ai-practitioner-01/ai-practitioner-01-domain1.html","explanation":{"correctAnswer":"B. Monitor production performance and retrain when needed","correctReason":"MLOps includes monitoring production performance and retraining when data or model behavior changes. The key signal is model quality **degrades after deployment as conditions change**.","incorrectReasons":{"0":"Assumes production conditions never change and is not an MLOps monitoring strategy. Here, the deciding detail is model quality degrades after deployment as conditions change, so this option describes a different need.","2":"Changes the prediction target but does not address production drift or declining model quality. Here, the deciding detail is model quality degrades after deployment as conditions change, so this option describes a different need.","3":"Creates target labels or annotations for training data. Here, the deciding detail is model quality degrades after deployment as conditions change, so this option describes a different need."},"examClue":"model quality **degrades after deployment as conditions change**","examTip":"Signal: model quality **degrades after deployment as conditions change**. Decision rule: monitor and retrain as part of MLOps. Contrast: a one-time test result does not guarantee ongoing production quality.","transferCheck":"","rememberThis":"","takeaway":{"signal":"model quality **degrades after deployment as conditions change**","think":"monitor and retrain as part of MLOps","contrast":"a one-time test result does not guarantee ongoing production quality."}},"kodekloud":{"title":"KodeKloud: ML Development Lifecycle and the ML Pipeline","url":"https://notes.kodekloud.com/docs/AWS-Certified-AI-Practitioner/Fundamentals-of-AI-and-ML/ML-Development-Lifecycle-and-the-ML-Pipeline/page"}}]};
